import { test } from 'node:test';
import assert from 'node:assert/strict';
import { total, itemCount } from '../src/cart.js';

test('total without discount', () => {
  assert.equal(total([{ price: 100, qty: 2 }, { price: 50, qty: 1 }]), 250);
});

test('customer discount is applied once', () => {
  assert.equal(total([{ price: 1000, qty: 1 }], 0.1), 900);
});

test('bulk discount is applied once, after the customer discount', () => {
  const items = Array.from({ length: 10 }, () => ({ price: 1000, qty: 1 }));
  assert.equal(total(items, 0.1), 8550);
});

test('bulk discount without customer discount is unchanged', () => {
  const items = Array.from({ length: 10 }, () => ({ price: 1000, qty: 1 }));
  assert.equal(total(items), 9500);
  assert.equal(total(items, 0), 9500);
});

test('9 lines do not get the bulk discount', () => {
  const items = Array.from({ length: 9 }, () => ({ price: 1000, qty: 1 }));
  assert.equal(total(items, 0.1), 8100);
});

test('item count', () => {
  assert.equal(itemCount([{ price: 1, qty: 3 }, { price: 1, qty: 2 }]), 5);
});
